using LigaVolley.Domain.Divisions; using LigaVolley.Domain.People; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace LigaVolley.Infrastructure.Persistence.Configurations;
internal sealed class PersonConfiguration:IEntityTypeConfiguration<Person>{public void Configure(EntityTypeBuilder<Person>b){b.ToTable("PERSON","dbo",t=>t.HasCheckConstraint("CK_PERSON_document","([document_type] IS NULL AND [document_number] IS NULL) OR ([document_type] IS NOT NULL AND [document_number] IS NOT NULL)"));b.HasKey(x=>x.PersonId).HasName("PK_PERSON");b.Property(x=>x.PersonId).HasColumnName("person_id").UseIdentityColumn();b.Property(x=>x.DocumentType).HasColumnName("document_type").HasColumnType("varchar(20)");b.Property(x=>x.DocumentNumber).HasColumnName("document_number").HasColumnType("varchar(30)");b.Property(x=>x.FirstName).HasColumnName("first_name").HasMaxLength(100).IsRequired();b.Property(x=>x.LastName).HasColumnName("last_name").HasMaxLength(100).IsRequired();b.Property(x=>x.BirthDate).HasColumnName("birth_date").HasColumnType("date");b.Property(x=>x.Gender).HasColumnName("gender").HasColumnType("char(1)").HasConversion(x=>x==null?null:x==Gender.Male?"M":"F",x=>x==null?null:x=="M"?Gender.Male:Gender.Female);b.Property(x=>x.Email).HasColumnName("email").HasMaxLength(200);b.Property(x=>x.Phone).HasColumnName("phone").HasMaxLength(50);b.Property(x=>x.Active).HasColumnName("active").HasDefaultValue(true);b.HasIndex(x=>new{x.DocumentType,x.DocumentNumber}).IsUnique().HasFilter("[document_type] IS NOT NULL AND [document_number] IS NOT NULL").HasDatabaseName("UX_PERSON_document");b.HasIndex(x=>new{x.LastName,x.FirstName,x.PersonId}).HasDatabaseName("IX_PERSON_name");}}
internal sealed class PersonAdditionalDocumentConfiguration:IEntityTypeConfiguration<PersonAdditionalDocument>{public void Configure(EntityTypeBuilder<PersonAdditionalDocument>b){b.ToTable("PERSON_ADDITIONAL_DOCUMENT","dbo",t=>t.HasCheckConstraint("CK_PERSON_ADDITIONAL_DOCUMENT_dates","[valid_to] IS NULL OR [valid_from] IS NULL OR [valid_to] >= [valid_from]"));b.HasKey(x=>x.PersonAdditionalDocumentId).HasName("PK_PERSON_ADDITIONAL_DOCUMENT");b.Property(x=>x.PersonAdditionalDocumentId).HasColumnName("person_additional_document_id").UseIdentityColumn();b.Property(x=>x.PersonId).HasColumnName("person_id");b.Property(x=>x.DocumentType).HasColumnName("document_type").HasColumnType("varchar(20)").HasConversion(x=>x==PersonAdditionalDocumentType.HealthCard?"HEALTH_CARD":"LEAGUE_CARD",x=>x=="HEALTH_CARD"?PersonAdditionalDocumentType.HealthCard:PersonAdditionalDocumentType.LeagueCard);b.Property(x=>x.DocumentNumber).HasColumnName("document_number").HasMaxLength(100);b.Property(x=>x.ValidFrom).HasColumnName("valid_from").HasColumnType("date");b.Property(x=>x.ValidTo).HasColumnName("valid_to").HasColumnType("date");b.Property(x=>x.Active).HasColumnName("active").HasDefaultValue(true);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(500);b.HasOne(x=>x.Person).WithMany(x=>x.AdditionalDocuments).HasForeignKey(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PERSON_ADDITIONAL_DOCUMENT_PERSON");b.HasIndex(x=>new{x.PersonId,x.DocumentType,x.Active}).HasDatabaseName("IX_PERSON_ADDITIONAL_DOCUMENT_lookup");}}
internal abstract class ProfileConfiguration<T>:IEntityTypeConfiguration<T> where T:class {protected abstract string Table{get;} protected abstract string KeyColumn{get;} protected abstract string KeyProperty{get;} public virtual void Configure(EntityTypeBuilder<T>b){b.ToTable(Table,"dbo");b.HasKey(KeyProperty).HasName($"PK_{Table}");b.Property<int>(KeyProperty).HasColumnName(KeyColumn).UseIdentityColumn();b.Property<int>("PersonId").HasColumnName("person_id");b.Property<bool>("Active").HasColumnName("active").HasDefaultValue(true);b.HasIndex("PersonId").IsUnique().HasDatabaseName($"UQ_{Table}_person");}}
internal sealed class PlayerConfiguration:ProfileConfiguration<Player>{protected override string Table=>"PLAYER";protected override string KeyColumn=>"player_id";protected override string KeyProperty=>"PlayerId";public override void Configure(EntityTypeBuilder<Player>b){base.Configure(b);b.HasOne(x=>x.Person).WithOne(x=>x.Player).HasForeignKey<Player>(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PLAYER_PERSON");}}
internal sealed class CoachConfiguration:ProfileConfiguration<Coach>{protected override string Table=>"COACH";protected override string KeyColumn=>"coach_id";protected override string KeyProperty=>"CoachId";public override void Configure(EntityTypeBuilder<Coach>b){base.Configure(b);b.HasOne(x=>x.Person).WithOne(x=>x.Coach).HasForeignKey<Coach>(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_COACH_PERSON");}}
internal sealed class RefereeConfiguration:ProfileConfiguration<Referee>{protected override string Table=>"REFEREE";protected override string KeyColumn=>"referee_id";protected override string KeyProperty=>"RefereeId";public override void Configure(EntityTypeBuilder<Referee>b){base.Configure(b);b.HasOne(x=>x.Person).WithOne(x=>x.Referee).HasForeignKey<Referee>(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_REFEREE_PERSON");}}
